const INK={r:.102,g:.118,b:.145}, GRAY={r:.49,g:.498,b:.533}, LIGHT={r:.949,g:.949,b:.953}, BORDER={r:.902,g:.906,b:.922}, BRAND={r:.408,g:.302,b:.925}, WHITE={r:1,g:1,b:1}, RED={r:1,g:.231,b:.188}, MUTED={r:.62,g:.64,b:.69};
const GS=[{position:0,color:{r:.569,g:.478,b:.992,a:1}},{position:1,color:{r:.384,g:.275,b:.918,a:1}}];
const solid=c=>[{type:"SOLID",color:c}];
const grad=(a)=>[{type:"GRADIENT_LINEAR",gradientStops:a||GS,gradientTransform:[[1,0,0],[0,1,0]]}];
const SH2={type:"DROP_SHADOW",color:{r:.07,g:.09,b:.18,a:.14},offset:{x:0,y:2},radius:8,spread:0,visible:true,blendMode:"NORMAL"};

async function T(chars,size,style,color,align,lh){
  const t=figma.createText();
  t.fontName={family:"Inter",style:style||"Regular"};
  t.characters=chars; t.fontSize=size; t.fills=solid(color||INK);
  if(align){t.textAlignHorizontal=align;}
  if(lh){t.lineHeight={value:lh,unit:"PIXELS"};}
  return t;
}
async function IC(id,w,h){
  const c=await figma.getNodeByIdAsync(id);
  const i=c.createInstance();
  if(w){i.resize(w,h||w);}
  return i;
}
function recolor(n,c){
  if(n.fills!==figma.mixed){
    const f=n.fills;
    if(Array.isArray(f)&&f.length>0&&f[0].visible!==false&&f[0].type!=="IMAGE"){n.fills=solid(c);}
  }
  if(n.strokes!==figma.mixed){
    const s=n.strokes;
    if(Array.isArray(s)&&s.length>0&&s[0].type!=="IMAGE"){n.strokes=solid(c);}
  }
  if(n.children){for(const ch of n.children)recolor(ch,c);}
}
function auto(dir,gap){
  const f=figma.createFrame();
  f.layoutMode=dir; f.itemSpacing=gap||0;
  f.primaryAxisSizingMode="AUTO"; f.counterAxisSizingMode="AUTO";
  f.fills=[];
  return f;
}
function fixed(w,h){const f=figma.createFrame();f.resize(w,h);f.fills=[];return f;}

