function getVar(setName,prop,val){const set=getComp(setName);return set.children.find(c=>c.name===prop+"="+val);}
async function shell(frame,statusWhite){
  const sb=await IC("1:33",375,44);
  if(statusWhite)recolor(sb,WHITE);
  sb.x=0;sb.y=0; frame.appendChild(sb);
  const hi=await IC("1:43",375,34);
  hi.x=0; hi.y=frame.height-34; frame.appendChild(hi);
}
function newFrame(name,x,y,h){
  const f=figma.createFrame();
  f.name=name; f.resize(375,h||812); f.x=x; f.y=y;
  f.fills=solid(WHITE); f.clipsContent=true;
  page.appendChild(f);
  return f;
}
async function sectionHeader(title,action){
  const sh=getComp("Section Header").createInstance();
  sh.findOne(n=>n.name==="Title").characters=title;
  const a=sh.findOne(n=>n.name==="Action");
  if(action){a.characters=action;}else{a.visible=false;}
  return sh;
}
// property card horizontal with data
async function propCardH(data){
  const c=getComp("Property Card · Horizontal").createInstance();
  const photo=c.findOne(n=>n.name==="Photo");
  const pc=await figma.getNodeByIdAsync(data.photoId);
  // swap photo: replace instance with new one inside wrapper is complex; instead detach approach:
  // simpler: remove old photo instance, create new
  const idx=c.children.indexOf(photo);
  photo.remove();
  const np=pc.createInstance(); np.resize(250,150); np.name="Photo"; np.x=0; np.y=0;
  c.insertChild(idx,np);
  c.findOne(n=>n.name==="Rating").characters=data.rating;
  c.findOne(n=>n.name==="Title").characters=data.title;
  c.findOne(n=>n.name==="Location").characters=data.location;
  const specs=c.findOne(n=>n.name==="Specs");
  if(specs){
    specs.findOne(n=>n.name==="Rooms").characters=data.rooms;
    specs.findOne(n=>n.name==="Area").characters=data.area;
  } else {
    c.findOne(n=>n.name==="Rooms").characters=data.rooms;
    c.findOne(n=>n.name==="Area").characters=data.area;
  }
  c.findOne(n=>n.name==="Price").characters=data.price;
  return c;
}
async function destCard(title,count,photoId){
  const c=getComp("Destination Card").createInstance();
  const photo=c.findOne(n=>n.name==="Photo");
  const idx=c.children.indexOf(photo);
  photo.remove();
  const pc=await figma.getNodeByIdAsync(photoId);
  const np=pc.createInstance(); np.resize(164,120); np.name="Photo"; np.x=0; np.y=0;
  c.insertChild(idx,np);
  c.findOne(n=>n.name==="Title").characters=title;
  c.findOne(n=>n.name==="Count").characters=count;
  return c;
}

