const INK={r:.102,g:.118,b:.145}, GRAY={r:.49,g:.498,b:.533}, LIGHT={r:.949,g:.949,b:.953}, BORDER={r:.902,g:.906,b:.922}, BRAND={r:.408,g:.302,b:.925}, WHITE={r:1,g:1,b:1}, MUTED={r:.62,g:.64,b:.69}, STAR={r:.98,g:.71,b:.196};
const solid=c=>[{type:"SOLID",color:c}];
async function T(chars,size,style,color,align,lh){
  const t=figma.createText();
  t.fontName={family:"Inter",style:style||"Regular"};
  t.characters=chars; t.fontSize=size; t.fills=solid(color||INK);
  if(align){t.textAlignHorizontal=align;}
  if(lh){t.lineHeight={value:lh,unit:"PIXELS"};}
  return t;
}
async function IC(id,w,h){const c=await figma.getNodeByIdAsync(id);const i=c.createInstance();if(w){i.resize(w,h||w);}return i;}
function recolor(n,c){
  if(n.fills!==figma.mixed){const f=n.fills;if(Array.isArray(f)&&f.length>0&&f[0].visible!==false&&f[0].type!=="IMAGE"){n.fills=solid(c);}}
  if(n.strokes!==figma.mixed){const s=n.strokes;if(Array.isArray(s)&&s.length>0&&s[0].type!=="IMAGE"){n.strokes=solid(c);}}
  if(n.children){for(const ch of n.children)recolor(ch,c);}
}
function auto(dir,gap){const f=figma.createFrame();f.layoutMode=dir;f.itemSpacing=gap||0;f.primaryAxisSizingMode="AUTO";f.counterAxisSizingMode="AUTO";f.fills=[];return f;}
function getComp(name){return compArea.children.find(c=>c.name===name);}
function getVar(setName,prop,val){const set=getComp(setName);return set.children.find(c=>c.name===prop+"="+val);}
async function shell(frame,statusWhite){
  const sb=await IC("1:33",375,44);
  if(statusWhite)recolor(sb,WHITE);
  sb.x=0;sb.y=0; frame.appendChild(sb);
  const hi=await IC("1:43",375,34);
  hi.x=0; hi.y=frame.height-34; frame.appendChild(hi);
}
function newFrame(name,x,y,h){
  const f=figma.createFrame();
  f.name=name; f.resize(375,h||812); f.x=x; f.y=y;
  f.fills=solid(WHITE); f.clipsContent=true;
  page.appendChild(f);
  return f;
}
async function sectionHeader(title,action){
  const sh=getComp("Section Header").createInstance();
  sh.findOne(n=>n.name==="Title").characters=title;
  const a=sh.findOne(n=>n.name==="Action");
  if(action){a.characters=action;}else{a.visible=false;}
  return sh;
}
async function stars(n,size){
  const row=auto("HORIZONTAL",2); row.counterAxisAlignItems="CENTER";
  for(let i=0;i<n;i++){const s=await IC("1:340",size||12,size||12);recolor(s,STAR);row.appendChild(s);}
  return row;
}

