function dump(name){
  const c=compArea.children.find(x=>x.name===name);
  function walk(n,d){
    let s="  ".repeat(d)+n.type+" "+n.name+" "+Math.round(n.width)+"x"+Math.round(n.height);
    if(n.type==="INSTANCE") s+=" [main:"+(n.mainComponent?n.mainComponent.name:"?")+"]";
    let out=[s];
    if(n.children&&d<4) for(const ch of n.children) out=out.concat(walk(ch,d+1));
    return out;
  }
  return walk(c,0).join("\n");
}
