const page = figma.root.children.find(p=>p.name.includes("03 · Workspace"));
const compArea = page.children.find(n=>n.name==="_Components (reusable)");
const cr = compArea.children.find(x=>x.name==="Chat Row");
const cb = compArea.children.find(x=>x.name==="Chat Bubble");
let log=[];
for(const v of cr.children){
  const ts = v.findAll(n=>n.type==="TEXT");
  // order: Name, Message, Time(in frame), Count
  // find by position: Name is in Frame col; Time is inside inner frame next to Message; Count is in right frame
  const name = ts.find(t=>t.characters==="Kari Rasmussen"||t.name==="Name");
  const msg = ts.find(t=>t.name==="Message");
  const time = ts.find(t=>t.characters==="14:30");
  const count = ts.find(t=>t.name==="Count");
  if(name) name.name="Name";
  if(msg) msg.name="Message";
  if(time){ time.name="Time"; time.characters="14:30"; }
  if(count){ count.name="Count"; count.characters="2"; }
  const badge = v.findOne(n=>n.name==="Badge");
  if(badge){
    if(v.name.includes("Read")&&!v.name.includes("Unread")){ badge.visible=false; if(count) count.visible=false; }
    else { badge.visible=true; if(count) count.visible=true; }
  }
  log.push(v.name+" fixed: "+ts.map(t=>t.name).join(","));
}
for(const v of cb.children){
  const ts = v.findAll(n=>n.type==="TEXT");
  // first Time = time, second Time = receipt
  let seen=0;
  for(const t of ts){
    if(t.name==="Time"){
      seen++;
      if(seen===2){ t.name="Receipt"; t.characters="✓✓"; }
    }
  }
  if(v.name.includes("Received")){
    const rec = v.findOne(n=>n.name==="Receipt");
    if(rec) rec.visible=false;
  } else {
    const rec = v.findOne(n=>n.name==="Receipt");
    if(rec) rec.visible=true;
  }
  log.push(v.name+" bubble fixed");
}
return log.join("\n");

