const page = figma.root.children.find(p=>p.name.includes("03 · Workspace"));
const compArea = page.children.find(n=>n.name==="_Components (reusable)");
const cb = compArea.children.find(x=>x.name==="Chat Bubble");
function walk(n,d){
  let out=["  ".repeat(d)+n.type+" "+n.name+" "+Math.round(n.width)+"x"+Math.round(n.height)+(n.type==="TEXT"?" '"+n.characters+"' vis="+n.visible:"")];
  if(n.children&&d<4) for(const c of n.children) out=out.concat(walk(c,d+1));
  return out;
}
return walk(cb.children[0],0).join("\n")+"\n---\n"+walk(cb.children[1],0).join("\n");

